'use strict';
(function(){
 const V=window.PhoenixCharacterVault,G=window.PhoenixCharacterGear,$=id=>document.getElementById(id),vault=V.createVault(()=>window.localStorage);
 let counter=0;const id=()=>window.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+(++counter)+'-'+Math.random().toString(36).slice(2);
 const initial=vault.read(),active=initial.builds.find(b=>b.id===initial.activeId);let draft=active?V.clone(active):V.newBuild(id()),opened=V.clone(draft),selected='chest',pending=null,designating=null,referencePushed=false;
 const title=s=>s[0].toUpperCase()+s.slice(1),piece=(b,s)=>G.items[b.equipment[s]],label=(b,s)=>piece(b,s)?.name||'Not selected';
 const make=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 const dirty=()=>JSON.stringify(draft)!==JSON.stringify(opened);
 function status(){const s=vault.status();$('save-status').textContent=s==='ready'?'':['unreadable','unsupported'].includes(s)?'Your saved Build Vault could not be read or uses an unsupported format. It is kept unchanged. This visit’s changes are not saved.':s==='changed-elsewhere'?'The Build Vault changed in another tab. Its saved record is kept unchanged. Export your session builds before reloading.':s==='write-failed'?'Saving failed. Your session builds remain available here; export them before leaving.':'Saving is unavailable. Session builds remain in memory; export them before leaving.';
 $('designation').textContent=vault.read().activeId===draft.id?'CURRENT IN-GAME BUILD · EDITING DRAFT':'BUILD EXPERIMENT';}
 function result(r,success){status();$('action-status').textContent=r.ok?success:r.reason==='name-conflict'?'That build name already exists. Choose another name; nothing was overwritten.':r.reason==='invalid'?'Check the build name and profile values before saving.':'Updated for this visit only. '+$('save-status').textContent;}
 function slot(s){const b=make('button');b.className='gear-slot'+(s===selected?' selected':'');b.setAttribute('aria-pressed',String(s===selected));b.append(make('strong',G.slots[s]),make('span',label(draft,s)));b.onclick=()=>{selected=s;render();$('choose-piece').focus();};return b;}
 function render(){for(const name of ['build-name','level','points','region']){const key={'build-name':'name',level:'level',points:'points',region:'region'}[name];$(name).value=draft[key]??'';}
 $('weapon-slots').replaceChildren();$('armor-slots').replaceChildren();for(const s of V.SLOTS)$(s==='steel'||s==='silver'?'weapon-slots':'armor-slots').append(slot(s));
 const p=piece(draft,selected);$('piece-title').textContent=G.slots[selected];$('piece-content').textContent=p?p.content:'';$('piece-description').textContent=label(draft,selected)+(p?' · '+G.requirement(p,draft.level).text:'');$('gear-reference').disabled=!p;
 $('illustration').textContent=piece(draft,'chest')?'Illustration: '+piece(draft,'chest').set+' set':'No chest piece selected';$('whole-tier').value='';status();}
 function review(next,summary){pending=next;$('review-summary').textContent=summary;const host=$('review-requirements');host.replaceChildren();for(const change of G.changes(draft,next)){const row=make('section');row.className='reference-requirement';row.append(make('h3',G.slots[change.slot]),make('p',change.requirement.text));host.append(row);}$('review').showModal();}
 for(const tier of G.tiers){const o=make('option',title(tier));o.value=tier;$('whole-tier').append(o);}
 $('whole-tier').onchange=e=>{if(!e.target.value)return;const next=V.clone(draft);for(const s of V.SLOTS)next.equipment[s]='feline-'+s+'-'+e.target.value;review(next,'Set all six pieces to '+title(e.target.value)+' Feline gear. This replaces each existing piece and any individual tier overrides.');};
 $('choose-piece').onclick=()=>{$('picker-title').textContent='Choose '+G.slots[selected].toLowerCase();const host=$('piece-options');host.replaceChildren();for(const tier of G.tiers){const p=G.items['feline-'+selected+'-'+tier],b=make('button');b.className='gear-slot';b.append(make('strong',p.name),make('span',p.content),make('span',G.requirement(p,draft.level).text));b.onclick=()=>{const next=V.clone(draft);next.equipment[selected]=p.id;$('picker').close();review(next,label(draft,selected)+' → '+p.name);};host.append(b);}$('picker').showModal();};
 $('apply-change').onclick=()=>{if(pending)draft=V.clone(pending);pending=null;$('review').close();render();$('action-status').textContent='Applied to the draft. Choose Save build to retain it.';};
 $('review').addEventListener('close',()=>{pending=null;$('whole-tier').value='';});
 for(const [field,key] of [['build-name','name'],['level','level'],['points','points'],['region','region']])$(field).oninput=e=>{draft[key]=['level','points'].includes(key)?e.target.value===''?null:Number(e.target.value):e.target.value;if(key==='level'){const p=piece(draft,selected);$('piece-description').textContent=label(draft,selected)+(p?' · '+G.requirement(p,draft.level).text:'');}};
 $('save-build').onclick=()=>{draft.name=draft.name.trim();const r=vault.save(draft);if(r.ok||!['invalid','name-conflict'].includes(r.reason))opened=V.clone(draft);result(r,'Build saved. Current-build designation is unchanged.');};
 $('copy-build').onclick=()=>{const name=prompt('Name this build copy',draft.name+' — experiment');if(!name?.trim())return;const copy=V.clone(draft);copy.id=id();copy.name=name.trim();const r=vault.save(copy);if(r.ok||!['invalid','name-conflict'].includes(r.reason)){draft=copy;opened=V.clone(copy);render();}result(r,'Build copy saved. Your previous build and current designation are unchanged.');};
 $('discard-build').onclick=()=>{draft=V.clone(opened);render();$('action-status').textContent='Draft restored to the build you last opened or saved.';};
 function canLeaveDraft(){return !dirty()||confirm('Discard this unsaved draft and open another build?');}
 function cards(){const host=$('build-cards');host.replaceChildren();const record=vault.read();for(const b of [...record.builds].sort((a,b)=>Number(b.id===record.activeId)-Number(a.id===record.activeId))){const card=make('article');card.className='build-card';card.append(make('h3',b.name),make('p',b.id===record.activeId?'Current in-game build':'Saved experiment'));const open=make('button','Open build');open.onclick=()=>{if(!canLeaveDraft())return;draft=V.clone(b);opened=V.clone(b);$('vault').close();render();};const current=make('button','Set as my current build');current.disabled=b.id===record.activeId;current.onclick=()=>{designating=b.id;const prior=record.builds.find(x=>x.id===record.activeId);const diffs=V.SLOTS.filter(s=>!prior||prior.equipment[s]!==b.equipment[s]).map(s=>G.slots[s]+': '+(prior?label(prior,s):'not designated')+' → '+label(b,s));for(const k of ['level','points','region'])if(!prior||prior[k]!==b[k])diffs.push(k+': '+(prior?.[k]??'not recorded')+' → '+(b[k]??'not recorded'));$('designation-summary').textContent='Designate “'+b.name+'” instead of '+(prior?'“'+prior.name+'”':'no current build')+'. '+(diffs.length?diffs.join('; '):'Equipment and profile are identical.');$('designation-review').showModal();};card.append(open,current);host.append(card);}if(!record.builds.length)host.append(make('p','No saved builds yet. Save a draft to start your Vault.'));}
 $('vault-open').onclick=()=>{cards();$('vault').showModal();};$('confirm-designation').onclick=()=>{const r=vault.designate(designating);$('designation-review').close();cards();status();result(r,'Current in-game build designated. Your open draft was not replaced.');};
 $('new-build').onclick=()=>{if(!canLeaveDraft())return;draft=V.newBuild(id(),'New experiment');opened=V.clone(draft);$('vault').close();render();};
 $('export-vault').onclick=()=>{const blob=new Blob([vault.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=make('a');a.href=url;a.download='phoenix-build-vault.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('action-status').textContent='Export requested. Unsaved draft edits are not included; save them to the session Vault first.';};
 function referenceRoute(hash){if(/^#gear(?:\/|$)/.test(location.hash))history.replaceState(null,'',hash);else{history.pushState(null,'',hash);referencePushed=true;}routeReference();}
 function catalogue(){const host=$('reference-body');$('reference-title').textContent='Shared Feline gear reference';host.replaceChildren(make('p','All supported tiers are visible. Source version 4.04; current Remastered requirements remain unverified.'));
  for(const [slot,label] of Object.entries(G.slots)){const section=make('section');section.append(make('h3',label));for(const tier of G.tiers){const item=G.items['feline-'+slot+'-'+tier],a=make('a',item.name+' · '+item.content);a.href='#gear/'+item.id;a.className='gear-reference-link';a.onclick=e=>{e.preventDefault();referenceRoute(a.getAttribute('href'));};section.append(a);}host.append(section);}}
 function openReference(item){if(!item){catalogue();$('reference-body').prepend(make('p','That gear entry was not found. Choose an available entry below.'));return;}
  $('reference-title').textContent=item.name;const host=$('reference-body');host.replaceChildren(make('p',item.content+' · Feline set · '+title(item.tier)),make('p',G.requirement(item,draft.level).text));
  host.append(make('p','Reference data: v'+item.provenance.version+', retrieved '+item.provenance.retrieved+'. Current Remastered verification pending.'),make('p','Combat stats, crafting costs and acquisition guidance are not yet verified for this entry.'));
  const a=make('a','Sources');a.className='sw-source-link';a.href='velen-sources.html#feline-gear';const back=make('button','Browse all supported gear');back.onclick=()=>referenceRoute('#gear');host.append(back,a);}
 $('catalogue-open').onclick=()=>referenceRoute('#gear');
 $('gear-reference').onclick=()=>{const item=piece(draft,selected);if(item)referenceRoute('#gear/'+item.id);};
 function routeReference(){const match=/^#gear(?:\/(.*))?$/.exec(location.hash);if(match){if(match[1])openReference(G.items[match[1]]);else catalogue();if(!$('reference').open)$('reference').showModal();}else if($('reference').open)$('reference').close();}
 function closeReference(){if(referencePushed){referencePushed=false;history.back();}else{history.replaceState(null,'',location.pathname+location.search);$('reference').close();}}
 $('reference').addEventListener('cancel',e=>{e.preventDefault();closeReference();});
 for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>{if(b.dataset.close==='reference')closeReference();else $(b.dataset.close).close();};
 addEventListener('popstate',routeReference);addEventListener('hashchange',routeReference);addEventListener('storage',e=>{if(e.key===V.KEY||e.key===null){$('action-status').textContent='Saved builds may have changed in another tab. Export any session work before reloading.';}});
 addEventListener('beforeunload',e=>{if(dirty()||(vault.status()!=='ready'&&vault.read().builds.length)){e.preventDefault();e.returnValue='';}});
 render();routeReference();
})();
